\set ON_ERROR_STOP on
SELECT CASE WHEN to_regclass('public.role') IS NULL THEN 'false' ELSE 'true' END AS smartur_existing_schema \gset
\if :smartur_existing_schema
\echo 'Existing SMARTUR schema detected; applying additive reconciliation only.'
BEGIN;
\else
BEGIN;

-- ============================================================
-- SMARTUR — Base de Datos v2 (2026)
-- Reconstrucción completa con soporte para:
--   • KYC empresa (4 fases de activación)
--   • Itinerarios / planificador de rutas
--   • Red social (seguir usuarios, likes)
--   • Reservas de servicios
--   • Chat turista ↔ empresa (polling)
-- Encoding recomendado: UTF8
--   CREATE DATABASE smartur WITH ENCODING 'UTF8' TEMPLATE template0;
-- ============================================================

-- ============================================================
-- 1. ROLES
-- ============================================================

CREATE TABLE role (
  role_id SERIAL PRIMARY KEY,
  name VARCHAR(50) NOT NULL
);

INSERT INTO role (name) VALUES ('admin'), ('user'), ('empresa'), ('turismologo');

-- ============================================================
-- 2. USUARIOS
-- ============================================================

CREATE TABLE "user" (
  user_id SERIAL PRIMARY KEY,
  name VARCHAR(50) NOT NULL,
  email VARCHAR(100) UNIQUE NOT NULL,
  password VARCHAR(255) NOT NULL,
  role_id INT NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  photo_url VARCHAR(512) NULL,
  avatar_icon_key VARCHAR(64) NULL,
  birth_date DATE NULL,
  bio VARCHAR(300) NULL,
  is_public BOOLEAN NOT NULL DEFAULT TRUE,
  email_verified BOOLEAN DEFAULT FALSE,
  is_seeded BOOLEAN NOT NULL DEFAULT FALSE,
  email_verification_token VARCHAR(255) NULL,
  email_verification_otp VARCHAR(255) NULL,
  email_verification_expires TIMESTAMP NULL,
  auth_provider VARCHAR(20) NOT NULL DEFAULT 'local',
  id_company INT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (role_id) REFERENCES role(role_id)
);

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_user_updated_at
    BEFORE UPDATE ON "user"
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE INDEX idx_user_role ON "user"(role_id);
CREATE INDEX idx_user_created_at ON "user"(created_at DESC);

-- ============================================================
-- 3. PERFIL VIAJERO (ML features)
-- ============================================================

CREATE TABLE traveler_profile (
  id_profile SERIAL PRIMARY KEY,
  user_id INT UNIQUE NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  age INT,
  age_range VARCHAR(10),
  gender VARCHAR(20),
  interests TEXT[],
  activity_level INT DEFAULT 3,
  budget VARCHAR(20),
  preferred_place VARCHAR(50),
  travel_type VARCHAR(50),
  has_accessibility BOOLEAN DEFAULT FALSE,
  accessibility_detail TEXT,
  has_visited_before BOOLEAN DEFAULT FALSE,
  restrictions TEXT,
  sustainable_preferences BOOLEAN DEFAULT FALSE,
  FOREIGN KEY (user_id) REFERENCES "user"(user_id) ON DELETE CASCADE
);

CREATE INDEX idx_profile_user_id ON traveler_profile(user_id);

-- ============================================================
-- 4. UBICACIONES
-- ============================================================

CREATE TABLE location (
  id_location SERIAL PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  state VARCHAR(100),
  municipality VARCHAR(100),
  latitude DECIMAL(10,6),
  longitude DECIMAL(10,6)
);

-- ============================================================
-- 5. TIPOS DE TURISMO
-- ============================================================

CREATE TABLE tourism_type (
  id_type SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL
);

-- ============================================================
-- 6. PUNTOS DE INTERÉS
-- ============================================================

CREATE TABLE point_of_interest (
  id SERIAL PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  categories_raw TEXT NOT NULL,
  categories_mapped JSONB NOT NULL DEFAULT '[]'::jsonb,
  price_level SMALLINT NOT NULL DEFAULT 2,
  is_accessible BOOLEAN NOT NULL DEFAULT FALSE,
  outdoor BOOLEAN NOT NULL DEFAULT FALSE,
  latitude DECIMAL(10,6),
  longitude DECIMAL(10,6),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  id_location INT REFERENCES location(id_location),
  description TEXT,
  image_url TEXT,
  rating DECIMAL(2,1) DEFAULT 4.0,
  validation_status VARCHAR(20) NOT NULL DEFAULT 'active'
    CHECK (validation_status IN ('pending_validation', 'active', 'rejected')),
  submitted_by_company_id INT,
  reviewed_by_admin_id INT REFERENCES "user"(user_id) ON DELETE SET NULL,
  validation_rejection_reason TEXT,
  validation_submitted_at TIMESTAMPTZ
);

CREATE INDEX idx_poi_created_at ON point_of_interest(created_at DESC);
CREATE INDEX idx_poi_price_level ON point_of_interest(price_level);
CREATE INDEX idx_poi_categories_mapped ON point_of_interest USING GIN (categories_mapped);

-- ============================================================
-- 7. GASTO TURÍSTICO
-- ============================================================

CREATE TABLE tourism_expenditure (
  id_expenditure SERIAL PRIMARY KEY,
  id_tourist INT,
  expenditure_type VARCHAR(50),
  amount NUMERIC(10,2),
  date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  destination VARCHAR(150),
  FOREIGN KEY (id_tourist) REFERENCES "user"(user_id)
);

-- ============================================================
-- 8. SECTORES TURÍSTICOS
-- ============================================================

CREATE TABLE tourism_sector (
  id_sector SERIAL PRIMARY KEY,
  name VARCHAR(100) UNIQUE NOT NULL,
  description TEXT
);

-- ============================================================
-- 9. EMPRESAS
-- status: pending_docs → documents_submitted → active / rejected / suspended
-- ============================================================

CREATE TABLE company (
  id_company SERIAL PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  address VARCHAR(255),
  phone VARCHAR(50),
  id_sector INT NOT NULL,
  id_location INT,
  owner_user_id INT NULL,
  status VARCHAR(25) NOT NULL DEFAULT 'pending_docs',
  registration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  is_certified BOOLEAN NOT NULL DEFAULT FALSE,
  certified_at TIMESTAMPTZ,
  FOREIGN KEY (id_sector) REFERENCES tourism_sector(id_sector),
  FOREIGN KEY (id_location) REFERENCES location(id_location),
  CONSTRAINT company_status_check CHECK (status IN (
    'pending_docs', 'documents_submitted', 'active', 'rejected', 'suspended'
  ))
);

-- FK circular user <-> company (se agrega al final de la sección user)
ALTER TABLE "user"
  ADD CONSTRAINT fk_user_company
    FOREIGN KEY (id_company) REFERENCES company(id_company) ON DELETE SET NULL;
ALTER TABLE "user"
  ADD COLUMN IF NOT EXISTS is_seeded BOOLEAN NOT NULL DEFAULT FALSE;

-- The built-in tourism account is fixture data and must never train WELLTUR.
UPDATE "user" SET is_seeded = TRUE
 WHERE role_id = 2 AND name = 'Foro Gastronómico 2026';

-- FK circular point_of_interest <-> company (se agrega tras definir company)
ALTER TABLE point_of_interest
  ADD CONSTRAINT point_of_interest_submitted_by_company_id_fkey
    FOREIGN KEY (submitted_by_company_id) REFERENCES company(id_company) ON DELETE SET NULL;

-- ============================================================
-- 10. VERIFICACIÓN KYC DE EMPRESA
-- ============================================================

CREATE TABLE company_verification (
  id_verification SERIAL PRIMARY KEY,
  id_company INT NOT NULL REFERENCES company(id_company) ON DELETE CASCADE UNIQUE,
  owner_full_name VARCHAR(200),
  owner_birth_date DATE,
  owner_curp VARCHAR(18),
  owner_rfc VARCHAR(13),
  owner_street VARCHAR(200),
  owner_colonia VARCHAR(100),
  owner_municipio VARCHAR(100),
  owner_state VARCHAR(100),
  owner_zip VARCHAR(10),
  ine_front_url VARCHAR(500),
  ine_back_url VARCHAR(500),
  address_proof_url VARCHAR(500),
  submitted_at TIMESTAMP,
  reviewed_at TIMESTAMP,
  reviewer_id INT REFERENCES "user"(user_id),
  rejection_reason TEXT,
  resubmission_count INT DEFAULT 0
);

-- ============================================================
-- 10b. FAQ DE EMPRESA (chatbot turista ↔ empresa)
-- ============================================================

CREATE TABLE IF NOT EXISTS company_faq (
  id_faq         SERIAL PRIMARY KEY,
  id_company     INT NOT NULL REFERENCES company(id_company) ON DELETE CASCADE,
  question       TEXT NOT NULL,
  answer         TEXT NOT NULL,
  search_vector  TSVECTOR GENERATED ALWAYS AS (
    to_tsvector('spanish', coalesce(question, '') || ' ' || coalesce(answer, ''))
  ) STORED,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_company_faq_search  ON company_faq USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS idx_company_faq_company ON company_faq(id_company);

-- ============================================================
-- 10c. BITÁCORA DE CAMBIOS DE ADMIN (disputas y validación KYC)
-- ============================================================

CREATE TABLE IF NOT EXISTS admin_change_log (
  id                   SERIAL PRIMARY KEY,
  target_type          VARCHAR(20)  NOT NULL CHECK (target_type IN ('service', 'company', 'user')),
  target_id            INTEGER      NOT NULL,
  admin_id             INTEGER      REFERENCES "user"(user_id) ON DELETE SET NULL,
  id_company           INTEGER      REFERENCES company(id_company) ON DELETE SET NULL,
  changes              JSONB        NOT NULL,
  status               VARCHAR(30)  NOT NULL DEFAULT 'pending_review'
                           CHECK (status IN ('pending_review', 'accepted', 'disputed', 'resolved_admin', 'resolved_empresa')),
  empresa_note         TEXT,
  empresa_counter      JSONB,
  admin_resolution_note TEXT,
  created_at           TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_acl_company   ON admin_change_log(id_company, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_acl_status    ON admin_change_log(status);

-- ============================================================
-- 10d. CONFIGURACIÓN DE LA APP (clave/valor)
-- ============================================================

CREATE TABLE IF NOT EXISTS app_config (
  key        VARCHAR(100) PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO app_config (key, value) VALUES ('evaluation_min_score', '7')
  ON CONFLICT (key) DO NOTHING;

-- ============================================================
-- 11. ACTIVIDADES, EMPLEO, INSUMOS (datos estadísticos empresa)
-- ============================================================

CREATE TABLE tourist_activities (
  id_activity SERIAL PRIMARY KEY,
  id_company INT,
  is_active BOOLEAN DEFAULT TRUE,
  production_value NUMERIC(12,2),
  environmental_impact TEXT,
  social_impact TEXT,
  FOREIGN KEY (id_company) REFERENCES company(id_company)
);

CREATE TABLE tourism_employment (
  id_employment SERIAL PRIMARY KEY,
  id_company INT,
  position VARCHAR(100),
  contract_type VARCHAR(50),
  gender VARCHAR(20),
  salary NUMERIC(10,2),
  start_date DATE,
  FOREIGN KEY (id_company) REFERENCES company(id_company)
);

CREATE TABLE tourism_inputs (
  id_input SERIAL PRIMARY KEY,
  id_company INT,
  input_type VARCHAR(100),
  cost NUMERIC(10,2),
  consumption NUMERIC(10,2),
  carbon_footprint NUMERIC(10,2),
  FOREIGN KEY (id_company) REFERENCES company(id_company)
);

-- ============================================================
-- 12. PLANTILLAS DE EVALUACIÓN
-- ============================================================

CREATE TABLE evaluation_template (
  id_template SERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  version VARCHAR(20),
  service_type VARCHAR(50),
  active BOOLEAN DEFAULT true,
  creation_date TIMESTAMP
);

CREATE TABLE evaluation_criterion (
  id_criterion SERIAL PRIMARY KEY,
  id_template INTEGER REFERENCES evaluation_template(id_template),
  name VARCHAR(100),
  description TEXT,
  weight DECIMAL(3,2),
  order_index INTEGER,
  active BOOLEAN DEFAULT true,
  field_type VARCHAR(50) NOT NULL DEFAULT 'scale' CHECK (field_type IN ('text', 'multiple_choice', 'scale', 'checkbox', 'select')),
  is_required BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE evaluation_subcriterion (
  id_subcriterion SERIAL PRIMARY KEY,
  id_criterion INTEGER NOT NULL REFERENCES evaluation_criterion(id_criterion) ON DELETE CASCADE,
  description VARCHAR(255) NOT NULL,
  score DECIMAL(5,2) NOT NULL DEFAULT 0,
  order_index INTEGER NOT NULL DEFAULT 0,
  required_evidences TEXT[],
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ============================================================
-- 13. SERVICIOS TURÍSTICOS
-- status: pending_review | active | rejected
-- ============================================================

CREATE TABLE tourist_service (
  id_service SERIAL PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  description TEXT,
  id_company INT,
  id_location INT,
  service_type VARCHAR(50),
  active BOOLEAN DEFAULT true,
  image_url VARCHAR(500),
  price_from NUMERIC(10,2),
  price_to NUMERIC(10,2),
  currency VARCHAR(3) DEFAULT 'MXN',
  operating_hours JSONB,
  capacity INT,
  duration_minutes INT,
  contact_phone VARCHAR(30),
  status VARCHAR(20) NOT NULL DEFAULT 'pending_review',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (id_company) REFERENCES company(id_company),
  FOREIGN KEY (id_location) REFERENCES location(id_location),
  CONSTRAINT tourist_service_status_check CHECK (status IN ('pending_review', 'active', 'rejected'))
);

CREATE INDEX idx_tourist_service_status ON tourist_service(status);
CREATE INDEX idx_tourist_service_company ON tourist_service(id_company);

-- ============================================================
-- 13b. ACTIVIDADES DE SERVICIO (paradas de itinerario con actividad)
-- ============================================================

CREATE TABLE IF NOT EXISTS service_activity (
  id_activity     SERIAL PRIMARY KEY,
  id_service      INT NOT NULL REFERENCES tourist_service(id_service) ON DELETE CASCADE,
  name            VARCHAR(200) NOT NULL,
  description     TEXT,
  duration_minutes INT,
  price           NUMERIC(10,2),
  max_capacity    INT,
  features        JSONB NOT NULL DEFAULT '[]',
  is_active       BOOL NOT NULL DEFAULT TRUE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_service_activity_service ON service_activity(id_service);

-- ============================================================
-- 14. EVALUACIONES DE SERVICIOS
-- ============================================================

CREATE TABLE service_evaluation (
  id_evaluation SERIAL PRIMARY KEY,
  id_service INTEGER REFERENCES tourist_service(id_service),
  id_template INTEGER REFERENCES evaluation_template(id_template),
  evaluation_date DATE,
  evaluator_id INTEGER REFERENCES "user"(user_id),
  status VARCHAR(20),
  is_active BOOLEAN DEFAULT TRUE,
  total_score DECIMAL(4,2),
  evaluation_time INTEGER,
  general_observations TEXT,
  pdf_url VARCHAR(500),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
);

CREATE TABLE evaluation_detail (
  id_detail SERIAL PRIMARY KEY,
  id_evaluation INTEGER REFERENCES service_evaluation(id_evaluation),
  id_criterion INTEGER REFERENCES evaluation_criterion(id_criterion),
  assigned_score INTEGER CHECK (assigned_score BETWEEN 0 AND 10),
  id_selected_subcriterion INTEGER REFERENCES evaluation_subcriterion(id_subcriterion),
  observations TEXT,
  is_active BOOLEAN DEFAULT TRUE,
  attached_evidences JSON,
  created_at TIMESTAMP,
  UNIQUE (id_evaluation, id_criterion)
);

CREATE TABLE service_certification (
  id_certification SERIAL PRIMARY KEY,
  id_service INTEGER REFERENCES tourist_service(id_service),
  certification_type VARCHAR(100),
  obtainment_date DATE,
  expiration_date DATE,
  issuing_organization VARCHAR(100),
  evidence_url VARCHAR(255),
  status VARCHAR(20),
  is_active BOOLEAN DEFAULT TRUE
);

-- ============================================================
-- 15. AUTH: TOKENS, RESET, REGISTRO PENDIENTE
-- ============================================================

CREATE TABLE IF NOT EXISTS login_tokens (
  user_id INT REFERENCES "user"(user_id) ON DELETE CASCADE,
  token VARCHAR(100) NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  used BOOLEAN DEFAULT FALSE
);

CREATE TABLE password_reset_tokens (
  id SERIAL PRIMARY KEY,
  user_id INT,
  token VARCHAR(100) NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  used BOOLEAN DEFAULT FALSE,
  FOREIGN KEY (user_id) REFERENCES "user"(user_id)
);

CREATE TABLE pending_registration (
  id SERIAL PRIMARY KEY,
  email VARCHAR(100) UNIQUE NOT NULL,
  name VARCHAR(50) NOT NULL,
  password VARCHAR(255) NOT NULL,
  company_name VARCHAR(100) NOT NULL,
  phone VARCHAR(20),
  id_sector INT NOT NULL,
  id_location INT,
  otp_hash VARCHAR(255) NOT NULL,
  otp_expires TIMESTAMP NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE refresh_tokens (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  -- session_id se agrega como FK más abajo, después de crear user_sessions
  session_id INT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  revoked BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_rt_user ON refresh_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user ON refresh_tokens(user_id);

-- ============================================================
-- 16. SEGURIDAD Y AUDITORÍA
-- ============================================================

CREATE TABLE security_events (
  id SERIAL PRIMARY KEY,
  event_type VARCHAR(100) NOT NULL,
  user_email VARCHAR(100),
  ip_address VARCHAR(50),
  severity VARCHAR(20) DEFAULT 'INFO',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_security_events_created_at ON security_events(created_at DESC);
CREATE INDEX idx_security_events_type ON security_events(event_type);

-- ============================================================
-- 17. APP MÓVIL: FAVORITOS, VISITAS, POSTS COMUNIDAD
-- ============================================================

CREATE TABLE user_favorite (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  place_kind VARCHAR(3) NOT NULL CHECK (place_kind IN ('svc', 'poi')),
  place_id INT NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  deleted_at TIMESTAMP NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (user_id, place_kind, place_id)
);
CREATE INDEX idx_user_favorite_user ON user_favorite(user_id);

CREATE TABLE user_visit (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  place_kind VARCHAR(3) NOT NULL CHECK (place_kind IN ('svc', 'poi')),
  place_id INT NOT NULL,
  visited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_user_visit_user_time ON user_visit(user_id, visited_at DESC);

CREATE TABLE community_post (
  id_post SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  caption TEXT NOT NULL DEFAULT '',
  image_url VARCHAR(512) NULL,
  place_kind VARCHAR(3) NOT NULL CHECK (place_kind IN ('svc', 'poi')),
  place_id INT NOT NULL,
  is_active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_community_post_created ON community_post(created_at DESC);

-- ============================================================
-- 18. CONTACTO / SUSCRIPCIONES LANDING
-- ============================================================

CREATE TABLE contact_subscription (
  id SERIAL PRIMARY KEY,
  email VARCHAR(255) NOT NULL,
  source VARCHAR(64) NOT NULL DEFAULT 'landing_b2b',
  reason VARCHAR(100) NULL,
  message TEXT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_contact_subscription_email ON contact_subscription(email);

-- ============================================================
-- 19. MODELO ML: SESIONES Y MÉTRICAS
-- ============================================================

CREATE TABLE ml_recommendation_session (
  id SERIAL PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  alpha DOUBLE PRECISION,
  best_algorithm VARCHAR(64),
  execution_time_ms DOUBLE PRECISION,
  context_json JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_ml_rec_session_user_created ON ml_recommendation_session (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ml_session_user ON ml_recommendation_session(user_id);

CREATE TABLE ml_recommendation_item (
  id SERIAL PRIMARY KEY,
  session_id INTEGER NOT NULL REFERENCES ml_recommendation_session(id) ON DELETE CASCADE,
  rank_pos INTEGER NOT NULL,
  item_id VARCHAR(64) NOT NULL,
  title VARCHAR(255),
  score DOUBLE PRECISION,
  pred_cf DOUBLE PRECISION,
  pred_rf DOUBLE PRECISION,
  pred_gbm DOUBLE PRECISION,
  kind VARCHAR(16) DEFAULT 'poi',
  image_url TEXT
);
CREATE INDEX idx_ml_rec_item_session ON ml_recommendation_item (session_id);

CREATE TABLE ml_model_metrics (
  id SERIAL PRIMARY KEY,
  metrics_json JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- K-fold cross-validation de los 3 algoritmos principales (CF, RF, GBM),
-- complementa el train/test split que ya guarda ml_model_metrics.
CREATE TABLE ml_cross_validation_metrics (
  id SERIAL PRIMARY KEY,
  cv_json JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================
-- 20. INTERACCIONES Y RATINGS DE USUARIOS (data collection ML)
-- ============================================================

CREATE TABLE user_interaction (
  id BIGSERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  place_kind VARCHAR(16) NULL,
  place_id INT NULL,
  event_type VARCHAR(32) NOT NULL,
  dwell_ms INT NULL,
  meta JSONB NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_user_interaction_user_place ON user_interaction (user_id, place_kind, place_id);
CREATE INDEX idx_user_interaction_created ON user_interaction (created_at DESC);

CREATE TABLE user_rating (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  place_kind VARCHAR(3) NOT NULL CHECK (place_kind IN ('svc', 'poi')),
  place_id INT NOT NULL,
  rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, place_kind, place_id)
);
CREATE INDEX idx_user_rating_place ON user_rating (place_kind, place_id);

CREATE TABLE ml_recommendation_feedback (
  id SERIAL PRIMARY KEY,
  session_id INT NOT NULL REFERENCES ml_recommendation_session(id) ON DELETE CASCADE,
  item_id VARCHAR(64) NOT NULL,
  rank_pos INT NOT NULL,
  clicked BOOLEAN NOT NULL DEFAULT FALSE,
  clicked_at TIMESTAMPTZ NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_ml_rec_feedback_session ON ml_recommendation_feedback (session_id);
ALTER TABLE ml_recommendation_feedback
  ADD CONSTRAINT uq_feedback_session_item UNIQUE (session_id, item_id);

-- ============================================================
-- 21. REPORTES DE POSTS
-- ============================================================

CREATE TABLE post_reports (
  id SERIAL PRIMARY KEY,
  post_id INT NOT NULL REFERENCES community_post(id_post) ON DELETE CASCADE,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  reason VARCHAR(50) NOT NULL CHECK (reason IN ('spam', 'inappropriate', 'false_info', 'hateful')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolved BOOLEAN NOT NULL DEFAULT FALSE,
  UNIQUE (post_id, user_id)
);
CREATE INDEX idx_post_reports_post ON post_reports (post_id);
CREATE INDEX idx_post_reports_resolved ON post_reports (resolved, created_at DESC);

-- ============================================================
-- 22. SESIONES DE DISPOSITIVO Y TOKENS FCM
-- ============================================================

CREATE TABLE user_sessions (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  device_hint VARCHAR(200) NULL,
  ip VARCHAR(50) NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '24 hours',
  last_seen TIMESTAMPTZ NULL,
  revoked BOOLEAN NOT NULL DEFAULT FALSE
);

ALTER TABLE refresh_tokens
  ADD CONSTRAINT fk_refresh_tokens_session
  FOREIGN KEY (session_id) REFERENCES user_sessions(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_session ON refresh_tokens(session_id);
CREATE INDEX idx_user_sessions_user ON user_sessions (user_id);

-- Login por QR: la web genera un reto, el móvil (ya logueado) lo aprueba
-- escaneándolo, y la web canjea el reto por una sesión real.
CREATE TABLE qr_login_sessions (
  id                   SERIAL PRIMARY KEY,
  challenge_token_hash TEXT NOT NULL UNIQUE,
  status               VARCHAR(10) NOT NULL DEFAULT 'pending'
                           CHECK (status IN ('pending','approved','denied','expired','consumed')),
  user_id              INT REFERENCES "user"(user_id) ON DELETE CASCADE,
  device_hint          VARCHAR(200),
  ip                   VARCHAR(50),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at           TIMESTAMPTZ NOT NULL DEFAULT NOW() + INTERVAL '2 minutes'
);
CREATE INDEX idx_qr_login_sessions_status ON qr_login_sessions(status, expires_at);

CREATE TABLE device_token (
  id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  token TEXT NOT NULL,
  platform VARCHAR(10) NOT NULL DEFAULT 'android',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, platform)
);
CREATE INDEX idx_device_token_user ON device_token(user_id);

-- ============================================================
-- 23. ITINERARIOS / RUTAS
-- ============================================================

CREATE TABLE itinerary (
  id_itinerary SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  title VARCHAR(200) NOT NULL,
  description TEXT,
  cover_image_url VARCHAR(500),
  is_public BOOLEAN DEFAULT FALSE,
  is_certified BOOLEAN DEFAULT FALSE,
  original_itinerary_id INT REFERENCES itinerary(id_itinerary) ON DELETE SET NULL,
  copy_count INT DEFAULT 0,
  view_count INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);

CREATE INDEX idx_itinerary_user ON itinerary(user_id);
CREATE INDEX idx_itinerary_public ON itinerary(is_public, copy_count DESC);
CREATE INDEX idx_itinerary_certified ON itinerary(is_certified) WHERE is_certified = TRUE;

CREATE TRIGGER update_itinerary_updated_at
    BEFORE UPDATE ON itinerary
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- ============================================================
-- 24. PARADAS DE ITINERARIO
-- ============================================================

CREATE TABLE itinerary_stop (
  id_stop SERIAL PRIMARY KEY,
  id_itinerary INT NOT NULL REFERENCES itinerary(id_itinerary) ON DELETE CASCADE,
  place_kind VARCHAR(3) NOT NULL CHECK (place_kind IN ('poi', 'svc')),
  place_id INT NOT NULL,
  stop_order INT NOT NULL,
  visit_date DATE,
  visit_time_start TIME,
  notes TEXT
);

CREATE INDEX idx_itinerary_stop_itinerary ON itinerary_stop(id_itinerary, stop_order);

-- ============================================================
-- 25. LIKES EN ITINERARIOS
-- ============================================================

CREATE TABLE itinerary_like (
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  id_itinerary INT NOT NULL REFERENCES itinerary(id_itinerary) ON DELETE CASCADE,
  created_at TIMESTAMP DEFAULT NOW(),
  PRIMARY KEY (user_id, id_itinerary)
);

CREATE INDEX idx_itinerary_like_itinerary ON itinerary_like(id_itinerary);

-- ============================================================
-- 26. RED SOCIAL: SEGUIMIENTO ENTRE USUARIOS
-- ============================================================

CREATE TABLE user_follow (
  follower_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  following_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  created_at TIMESTAMP DEFAULT NOW(),
  PRIMARY KEY (follower_id, following_id),
  CONSTRAINT no_self_follow CHECK (follower_id <> following_id)
);

CREATE INDEX idx_user_follow_following ON user_follow(following_id);

-- ============================================================
-- 27. RESERVAS DE SERVICIOS
-- status: pending | confirmed | cancelled
-- ============================================================

CREATE TABLE booking (
  id_booking SERIAL PRIMARY KEY,
  id_service INT NOT NULL REFERENCES tourist_service(id_service),
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  id_itinerary INT REFERENCES itinerary(id_itinerary) ON DELETE SET NULL,
  visit_date DATE NOT NULL,
  visit_time TIME,
  guests INT DEFAULT 1,
  notes TEXT,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  is_walkin BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP DEFAULT NOW(),
  CONSTRAINT booking_status_check CHECK (status IN ('pending', 'confirmed', 'cancelled'))
);

CREATE INDEX idx_booking_service ON booking(id_service);
CREATE INDEX idx_booking_user ON booking(user_id);
CREATE INDEX idx_booking_date ON booking(visit_date);

-- ============================================================
-- 28. CHAT: CONVERSACIONES Y MENSAJES (turista ↔ empresa)
-- ============================================================

CREATE TABLE conversation (
  id_conversation SERIAL PRIMARY KEY,
  tourist_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  id_company INT NOT NULL REFERENCES company(id_company) ON DELETE CASCADE,
  id_service INT REFERENCES tourist_service(id_service) ON DELETE SET NULL,
  created_at TIMESTAMP DEFAULT NOW(),
  UNIQUE (tourist_id, id_company, id_service)
);

CREATE INDEX idx_conversation_tourist ON conversation(tourist_id);
CREATE INDEX idx_conversation_company ON conversation(id_company);

CREATE TABLE message (
  id_message SERIAL PRIMARY KEY,
  id_conversation INT NOT NULL REFERENCES conversation(id_conversation) ON DELETE CASCADE,
  sender_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  read_at TIMESTAMP,
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE INDEX idx_message_conversation ON message(id_conversation, created_at DESC);

-- ============================================================
-- WELLTUR: TURISMO DE BIENESTAR (Wellness)
-- ============================================================

CREATE TABLE IF NOT EXISTS wellness_destination (
  dest_id          SERIAL PRIMARY KEY,
  nombre_lugar     VARCHAR(200) NOT NULL,
  estado           VARCHAR(100),
  municipio        VARCHAR(100),
  lat              NUMERIC(9, 6),
  lon              NUMERIC(9, 6),
  nivel_aislamiento    NUMERIC(4, 3) CHECK (nivel_aislamiento BETWEEN 0 AND 1),
  restauracion_pasiva  NUMERIC(4, 3) CHECK (restauracion_pasiva BETWEEN 0 AND 1),
  demanda_fisica       NUMERIC(4, 3) CHECK (demanda_fisica BETWEEN 0 AND 1),
  categoria_wellness   VARCHAR(50),
  wellness_sentiment_score NUMERIC(5, 4) DEFAULT 0.5000 CHECK (wellness_sentiment_score BETWEEN 0 AND 1),
  descripcion          TEXT,
  fuente               VARCHAR(100) DEFAULT 'manual',
  activo               BOOLEAN DEFAULT TRUE,
  created_at           TIMESTAMP DEFAULT NOW(),
  poi_fk_id            INT REFERENCES point_of_interest(id) ON DELETE SET NULL,
  service_fk_id        INT REFERENCES tourist_service(id_service) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_wellness_dest_categoria    ON wellness_destination (categoria_wellness);
CREATE INDEX IF NOT EXISTS idx_wellness_dest_estado       ON wellness_destination (estado);
CREATE INDEX IF NOT EXISTS idx_wellness_dest_aislamiento  ON wellness_destination (nivel_aislamiento);
CREATE INDEX IF NOT EXISTS idx_wellness_dest_restauracion ON wellness_destination (restauracion_pasiva);

CREATE TABLE IF NOT EXISTS stress_assessment (
  assessment_id    SERIAL PRIMARY KEY,
  user_id          INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  q1_energia       SMALLINT NOT NULL CHECK (q1_energia BETWEEN 1 AND 4),
  q2_tension       SMALLINT NOT NULL CHECK (q2_tension BETWEEN 1 AND 4),
  q3_rumiacion     SMALLINT NOT NULL CHECK (q3_rumiacion BETWEEN 1 AND 4),
  q4_activacion    SMALLINT NOT NULL CHECK (q4_activacion BETWEEN 1 AND 4),
  modo_viaje       VARCHAR(30) NOT NULL,
  perfil_interno   VARCHAR(30),
  confianza_ml     NUMERIC(4, 3),
  metodo_decision  VARCHAR(20),
  consent_given    BOOLEAN NOT NULL DEFAULT FALSE,
  consent_at       TIMESTAMP,
  created_at       TIMESTAMP DEFAULT NOW(),
  app_version      VARCHAR(20),
  CONSTRAINT chk_stress_consent CHECK (consent_given = TRUE)
);

CREATE INDEX IF NOT EXISTS idx_stress_assessment_user    ON stress_assessment (user_id);
CREATE INDEX IF NOT EXISTS idx_stress_assessment_modo    ON stress_assessment (modo_viaje);
CREATE INDEX IF NOT EXISTS idx_stress_assessment_created ON stress_assessment (created_at DESC);

CREATE TABLE IF NOT EXISTS wellness_recommendation_session (
  session_id        SERIAL PRIMARY KEY,
  user_id           INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  assessment_id     INT REFERENCES stress_assessment(assessment_id) ON DELETE SET NULL,
  modo_viaje        VARCHAR(30) NOT NULL,
  recommended_ids   JSONB NOT NULL DEFAULT '[]',
  top_n             SMALLINT DEFAULT 3,
  algorithm_version VARCHAR(20) DEFAULT '1.0',
  created_at        TIMESTAMP DEFAULT NOW()
);

-- Welltur preference profiles are kept separate from the legacy stress screener.
-- They capture explicit trip intent and must never be interpreted as health data.
CREATE TABLE IF NOT EXISTS wellness_preference_assessment (
  preference_assessment_id SERIAL PRIMARY KEY,
  user_id             INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  wellness_dimensions TEXT[] NOT NULL CHECK (cardinality(wellness_dimensions) BETWEEN 1 AND 3),
  activity_level      VARCHAR(20) NOT NULL CHECK (activity_level IN ('low','moderate','high')),
  region_filter       VARCHAR(100),
  consent_given       BOOLEAN NOT NULL CHECK (consent_given = TRUE),
  consent_at          TIMESTAMP NOT NULL DEFAULT NOW(),
  created_at          TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_wellness_preference_dimensions CHECK (
    wellness_dimensions <@ ARRAY['physical','mental','emotional','spiritual','social','environmental']::TEXT[]
  )
);

-- WELLTUR M/W: preferencias de búsqueda por viaje. Separadas del marco GWI
-- y de cualquier evaluación de estrés/salud.
CREATE TABLE IF NOT EXISTS wellness_trip_preference_assessment (
  trip_preference_id SERIAL PRIMARY KEY,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  motive_priorities TEXT[] NOT NULL DEFAULT '{}',
  modality_preferences TEXT[] NOT NULL DEFAULT '{}',
  max_effort SMALLINT NOT NULL DEFAULT 3 CHECK (max_effort BETWEEN 1 AND 3),
  needs_accessible BOOLEAN NOT NULL DEFAULT FALSE,
  region_filter VARCHAR(100),
  consent_given BOOLEAN NOT NULL CHECK (consent_given = TRUE),
  consent_at TIMESTAMP NOT NULL DEFAULT NOW(),
  questionnaire_version VARCHAR(20) NOT NULL DEFAULT 'mw-1.5',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT chk_welltur_mw_motives CHECK (
    cardinality(motive_priorities) <= 3 AND motive_priorities <@ ARRAY[
      'M1','M2','M3','M4','M5','M6','M7','M8','M9'
    ]::TEXT[]
  ),
  CONSTRAINT chk_welltur_mw_modalities CHECK (
    cardinality(modality_preferences) <= 3 AND modality_preferences <@ ARRAY[
      'W1','W2','W3','W4','W5','W6','W7'
    ]::TEXT[]
  ),
  CONSTRAINT chk_welltur_mw_not_empty CHECK (
    cardinality(motive_priorities) > 0 OR cardinality(modality_preferences) > 0
  )
);

CREATE INDEX IF NOT EXISTS idx_welltur_trip_pref_user_created
  ON wellness_trip_preference_assessment(user_id, created_at DESC);

ALTER TABLE wellness_recommendation_session
  ADD COLUMN IF NOT EXISTS preference_assessment_id INT
    REFERENCES wellness_preference_assessment(preference_assessment_id) ON DELETE SET NULL;

ALTER TABLE wellness_recommendation_session
  ADD COLUMN IF NOT EXISTS trip_preference_id INT
    REFERENCES wellness_trip_preference_assessment(trip_preference_id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_wellness_pref_user_created
  ON wellness_preference_assessment(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wellness_session_preference
  ON wellness_recommendation_session(preference_assessment_id);

CREATE INDEX IF NOT EXISTS idx_wellness_session_user       ON wellness_recommendation_session (user_id);
CREATE INDEX IF NOT EXISTS idx_wellness_session_assessment ON wellness_recommendation_session (assessment_id);
CREATE INDEX IF NOT EXISTS idx_wellness_session_modo       ON wellness_recommendation_session (modo_viaje);

CREATE TABLE IF NOT EXISTS wellness_satisfaction (
  sat_id        SERIAL PRIMARY KEY,
  session_id    INT NOT NULL REFERENCES wellness_recommendation_session(session_id) ON DELETE CASCADE,
  user_id       INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  fit_rating    SMALLINT NOT NULL CHECK (fit_rating BETWEEN 1 AND 5),
  feedback_text TEXT,
  created_at    TIMESTAMP DEFAULT NOW(),
  CONSTRAINT uq_wellness_sat_session UNIQUE (session_id)
);

CREATE INDEX IF NOT EXISTS idx_wellness_sat_user    ON wellness_satisfaction (user_id);
CREATE INDEX IF NOT EXISTS idx_wellness_sat_session ON wellness_satisfaction (session_id);

-- Reclamo de fichas del DENUE por empresas registradas (flujo B2B).
-- Una empresa pide "este negocio del DENUE soy yo"; un admin lo verifica. Al aprobarse, el
-- lugar queda ligado a la empresa (point_of_interest.submitted_by_company_id) y pasa a
-- mostrarse como verificado por SMARTUR en la app.
CREATE TABLE IF NOT EXISTS poi_claim (
  claim_id      SERIAL PRIMARY KEY,
  poi_id        INT NOT NULL REFERENCES point_of_interest(id) ON DELETE CASCADE,
  company_id    INT NOT NULL REFERENCES company(id_company) ON DELETE CASCADE,
  user_id       INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  evidencia     TEXT NOT NULL CHECK (char_length(evidencia) BETWEEN 10 AND 2000),
  status        VARCHAR(12) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  admin_notes   TEXT,
  reviewed_by   INT REFERENCES "user"(user_id) ON DELETE SET NULL,
  reviewed_at   TIMESTAMP,
  created_at    TIMESTAMP DEFAULT NOW()
);

-- Una sola solicitud pendiente por empresa y lugar.
CREATE UNIQUE INDEX IF NOT EXISTS uq_poi_claim_pendiente ON poi_claim (poi_id, company_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_poi_claim_status ON poi_claim (status);
CREATE INDEX IF NOT EXISTS idx_poi_claim_company ON poi_claim (company_id);

-- Feedback voluntario por experiencia mostrada, señal necesaria para evaluar
-- ranking de manera offline antes de considerar entrenar un modelo aprendido.
CREATE TABLE IF NOT EXISTS wellness_recommendation_item_feedback (
  feedback_id SERIAL PRIMARY KEY,
  session_id INT NOT NULL REFERENCES wellness_recommendation_session(session_id) ON DELETE CASCADE,
  user_id INT NOT NULL REFERENCES "user"(user_id) ON DELETE CASCADE,
  item_id VARCHAR(100) NOT NULL,
  event_type VARCHAR(20) NOT NULL CHECK (event_type IN ('impression','opened','saved','dismissed','selected','visited','rated')),
  position SMALLINT CHECK (position BETWEEN 1 AND 10),
  motive_tags_snapshot TEXT[] NOT NULL DEFAULT '{}',
  modality_tags_snapshot TEXT[] NOT NULL DEFAULT '{}',
  rating SMALLINT CHECK (rating BETWEEN 1 AND 5),
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_wellness_item_feedback UNIQUE (session_id, item_id, event_type),
  CONSTRAINT chk_wellness_feedback_tag_snapshot CHECK (
    motive_tags_snapshot <@ ARRAY['M1','M2','M3','M4','M5','M6','M7','M8','M9']::TEXT[] AND
    modality_tags_snapshot <@ ARRAY['W1','W2','W3','W4','W5','W6','W7']::TEXT[]
  ),
  CONSTRAINT chk_wellness_item_rating CHECK (
    (event_type = 'rated' AND rating IS NOT NULL) OR
    (event_type <> 'rated' AND rating IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS idx_wellness_item_feedback_training
  ON wellness_recommendation_item_feedback(event_type, created_at DESC);

-- Columnas wellness de revisión en servicios y POIs
ALTER TABLE tourist_service
  ADD COLUMN IF NOT EXISTS is_wellness             BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS wellness_status          VARCHAR(20) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS categoria_wellness       VARCHAR(50),
  ADD COLUMN IF NOT EXISTS nivel_aislamiento        NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS restauracion_pasiva      NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS demanda_fisica           NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS wellness_sentiment_score NUMERIC(5, 4),
  ADD COLUMN IF NOT EXISTS descripcion_bienestar    TEXT,
  ADD COLUMN IF NOT EXISTS wellness_admin_notes     TEXT,
  ADD COLUMN IF NOT EXISTS wellness_reviewed_at     TIMESTAMP,
  ADD COLUMN IF NOT EXISTS wellness_reviewed_by     INT REFERENCES "user"(user_id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS wellness_dimensions     TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_evidence       TEXT,
  ADD COLUMN IF NOT EXISTS wellness_motives        TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_modalities     TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_mw_evidence    JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS wellness_mw_reviewed_at TIMESTAMP;

ALTER TABLE point_of_interest
  ADD COLUMN IF NOT EXISTS is_wellness             BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS wellness_status          VARCHAR(20) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS categoria_wellness       VARCHAR(50),
  ADD COLUMN IF NOT EXISTS nivel_aislamiento        NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS restauracion_pasiva      NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS demanda_fisica           NUMERIC(4, 3),
  ADD COLUMN IF NOT EXISTS wellness_sentiment_score NUMERIC(5, 4),
  ADD COLUMN IF NOT EXISTS descripcion_bienestar    TEXT,
  ADD COLUMN IF NOT EXISTS wellness_admin_notes     TEXT,
  ADD COLUMN IF NOT EXISTS wellness_reviewed_at     TIMESTAMP,
  ADD COLUMN IF NOT EXISTS wellness_reviewed_by     INT REFERENCES "user"(user_id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS wellness_dimensions     TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_evidence       TEXT,
  ADD COLUMN IF NOT EXISTS wellness_motives        TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_modalities     TEXT[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS wellness_mw_evidence    JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS wellness_mw_reviewed_at TIMESTAMP;

ALTER TABLE traveler_profile
  ADD COLUMN IF NOT EXISTS wellness_consent    BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS wellness_consent_at TIMESTAMP,
  ADD COLUMN IF NOT EXISTS wellness_active     BOOLEAN DEFAULT FALSE;

-- Estado de revisión wellness restringido a pendiente/aprobado/rechazado
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_poi_wellness_status') THEN
    ALTER TABLE point_of_interest ADD CONSTRAINT chk_poi_wellness_status
      CHECK (wellness_status IN ('pending','approved','rejected') OR wellness_status IS NULL);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_ts_wellness_status') THEN
    ALTER TABLE tourist_service ADD CONSTRAINT chk_ts_wellness_status
      CHECK (wellness_status IN ('pending','approved','rejected') OR wellness_status IS NULL);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_poi_wellness_dimensions') THEN
    ALTER TABLE point_of_interest ADD CONSTRAINT chk_poi_wellness_dimensions
      CHECK (wellness_dimensions <@ ARRAY['physical','mental','emotional','spiritual','social','environmental']::TEXT[]);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_ts_wellness_dimensions') THEN
    ALTER TABLE tourist_service ADD CONSTRAINT chk_ts_wellness_dimensions
      CHECK (wellness_dimensions <@ ARRAY['physical','mental','emotional','spiritual','social','environmental']::TEXT[]);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_poi_welltur_mw_tags') THEN
    ALTER TABLE point_of_interest ADD CONSTRAINT chk_poi_welltur_mw_tags CHECK (
      cardinality(wellness_motives) <= 9 AND
      wellness_motives <@ ARRAY['M1','M2','M3','M4','M5','M6','M7','M8','M9']::TEXT[] AND
      cardinality(wellness_modalities) <= 7 AND
      wellness_modalities <@ ARRAY['W1','W2','W3','W4','W5','W6','W7']::TEXT[] AND
      (wellness_mw_reviewed_at IS NULL OR
        (cardinality(wellness_motives) + cardinality(wellness_modalities) > 0 AND
         wellness_mw_evidence ?& (wellness_motives || wellness_modalities)))
    );
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_ts_welltur_mw_tags') THEN
    ALTER TABLE tourist_service ADD CONSTRAINT chk_ts_welltur_mw_tags CHECK (
      cardinality(wellness_motives) <= 9 AND
      wellness_motives <@ ARRAY['M1','M2','M3','M4','M5','M6','M7','M8','M9']::TEXT[] AND
      cardinality(wellness_modalities) <= 7 AND
      wellness_modalities <@ ARRAY['W1','W2','W3','W4','W5','W6','W7']::TEXT[] AND
      (wellness_mw_reviewed_at IS NULL OR
        (cardinality(wellness_motives) + cardinality(wellness_modalities) > 0 AND
         wellness_mw_evidence ?& (wellness_motives || wellness_modalities)))
    );
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_poi_wellness_status
  ON point_of_interest(wellness_status) WHERE wellness_status IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ts_wellness_status
  ON tourist_service(wellness_status) WHERE wellness_status IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_poi_welltur_mw_reviewed
  ON point_of_interest(wellness_mw_reviewed_at) WHERE wellness_mw_reviewed_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_ts_welltur_mw_reviewed
  ON tourist_service(wellness_mw_reviewed_at) WHERE wellness_mw_reviewed_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_poi_validation_status ON point_of_interest(validation_status);

-- Conteo de servicios/POIs pendientes de validación wellness (AdminBadgesContext)
CREATE OR REPLACE VIEW wellness_pending_count AS
SELECT (
  (SELECT COUNT(*) FROM tourist_service  WHERE wellness_status = 'pending') +
  (SELECT COUNT(*) FROM point_of_interest WHERE wellness_status = 'pending')
) AS total_pending;

